-- Seeds the canonical CATIA licence sheet into the shared document.
--
-- migration_catia_license.sql creates the row with license_costs = '{}', which
-- CatiaLicenseService.load() reports as "no document". Until someone publishes,
-- the app falls back to the first admin's browser copy. This migration publishes
-- the authoritative sheet instead, so no client ever decides it.
--
-- Values are generated verbatim from stores/useCatiaStore.ts (defaultLicenseCosts
-- / defaultLicenseRevenues) — 7 licences x 52 month slots covering 2023-09..2027-12.
--
-- Safe to re-run: the WHERE clause only touches a document that was never
-- published, so a real sheet already in the table is left alone.
--
-- updated_by stays null: auth.uid() is null in the SQL editor, and the column is
-- nullable precisely so a migration can write the document without a user.

insert into public.catia_license_data (id, license_costs, license_revenues, updated_at)
values (
  'default',
