on conflict (id) do update
  set license_costs   = excluded.license_costs,
      license_revenues = excluded.license_revenues,
      updated_at      = excluded.updated_at
  where public.catia_license_data.license_costs is null
     or public.catia_license_data.license_costs = '{}'::jsonb;

-- Verify: expect 7 rows, licences 1..7, 52 slots each.
select key::int as license_id,
       jsonb_array_length(value) as slots
from public.catia_license_data,
     lateral jsonb_each(license_costs)
where id = 'default'
order by 1;
